import {controller, target} from '@github/catalyst'

@controller
export class TwoFactorSetupSwitchSelectionElement extends HTMLElement {
  @target declare box: HTMLElement
  @target declare smsElem: HTMLElement
  @target declare appElem: HTMLElement

  #eventAbortController: AbortController | null = null

  connectedCallback() {
    // abort signal will be sent when the event listener needs to be cleaned up
    const {signal} = (this.#eventAbortController = new AbortController())
    // `verify-done` event is triggered by the two-factor-setup/verification controller
    // afaik, this is necessary for adjacent event listening (https://github.github.io/catalyst/guide/patterns/#registering-global-or-many-event-listeners)
    this.addEventListener('verify-done', this.hide, {signal})
    this.addEventListener('init-done', this.show, {signal})
  }

  disconnectedCallback() {
    this.#eventAbortController?.abort()
  }

  hide() {
    this.box.hidden = true
  }

  show(event: Event) {
    const type = (event as CustomEvent).detail
    this.box.hidden = false
    if (type === 'sms') {
      this.smsElem.hidden = true
      this.appElem.hidden = false
    } else {
      this.appElem.hidden = true
      this.smsElem.hidden = false
    }
  }

  switchMethodApp() {
    this.switchMethodEvent('app')
  }

  switchMethodSms() {
    this.switchMethodEvent('sms')
  }

  switchMethodEvent(type: 'app' | 'sms') {
    const verificationElem = document.getElementById('two-factor-setup-verification-step') as HTMLElement
    if (verificationElem != null) {
      verificationElem.dispatchEvent(new CustomEvent('switch-selection', {detail: type}))
    }
  }
}
