import {announce} from '@github-ui/aria-live'
import {attr, controller, target} from '@github/catalyst'
import {debounce} from '@github/mini-throttle/decorators'
import {getBaseFetchHeaders} from '@github-ui/fetch-headers'

type VerifyResponse = {
  success: boolean
  error?: string
}

@controller
export class TwoFactorConfigureOtpFactorElement extends HTMLElement {
  // app targets
  @target declare appOtpInput: HTMLInputElement
  @target declare appForm: HTMLFormElement

  // sms targets
  @target declare smsInitialLoad: HTMLElement
  @target declare smsElem: HTMLElement
  @target declare smsPhoneInput: HTMLInputElement
  @target declare buttonSendSms: HTMLButtonElement
  @target declare smsOtpInput: HTMLInputElement
  @target declare countryCodeSelect: HTMLSelectElement
  @target declare smsForm: HTMLFormElement
  @target declare smsCodeForm: HTMLFormElement
  @target declare smsSendStatusSuccess: HTMLElement
  @target declare smsSendStatusInProgress: HTMLElement
  @target declare smsErrorContainer: HTMLElement
  @target declare smsDefaultError: HTMLElement
  @target declare smsSendStatusError: HTMLElement

  // common targets
  @target declare otpVerifySuccess: HTMLElement
  @target declare verifyError: HTMLElement
  @target declare saveButton: HTMLFormElement
  @target declare showButtons: HTMLElement
  @attr factorType = 'app'

  connectedCallback() {
    this.showSMS()
    this.showButtons.hidden = false
  }

  configuringApp(): boolean {
    return this.factorType === 'app'
  }

  showSMS() {
    if (!this.configuringApp()) {
      this.smsElem.hidden = false
    }
  }

  smsPhoneInputChange() {
    this.buttonSendSms.disabled = !this.smsPhoneInput.value
  }

  // method was taken from verification, we should look into putting this into a helper file
  setSmsControlState(inProgress: boolean, isSuccess: boolean, message?: string) {
    this.buttonSendSms.disabled = inProgress || isSuccess
    const isError = !inProgress && !isSuccess
    const showDefaultError = isError && !message
    const showServerError = isError && !!message

    if (showServerError) {
      this.smsErrorContainer.querySelector('.Banner-title')!.innerHTML = message!
      setTimeout(() => this.smsErrorContainer.focus(), 0)
    }
    if (showDefaultError) {
      setTimeout(() => this.smsDefaultError.focus(), 0)
    }

    this.smsSendStatusError.hidden = !isError
    this.smsSendStatusSuccess.hidden = inProgress || !isSuccess
    this.smsSendStatusInProgress.hidden = !inProgress
    this.smsDefaultError.hidden = !showDefaultError
    this.smsErrorContainer.hidden = !showServerError
    this.smsOtpInput.disabled = inProgress || isError

    if (isSuccess) {
      this.smsCodeForm.hidden = false
      this.smsOtpInput.focus()
    }
  }

  async buttonSendSmsClick() {
    if (this.buttonSendSms.hasAttribute('data-sudo-required')) {
      // sudo modal has not been completed, this will be refired after it is
      return
    }

    this.setSmsControlState(true, false)
    this.smsOtpInput.value = ''
    this.smsOtpInput.disabled = true

    const sendSmsUrl = this.buttonSendSms.getAttribute('data-url')!
    const csrfInput = this.smsForm.querySelector('.js-data-url-csrf-send') as HTMLInputElement
    const number = `${this.countryCodeSelect.value} ${this.smsPhoneInput.value}`
    const formData = new FormData()
    formData.append('number', number)
    formData.append('inline_configure', 'true')

    const octocaptchaToken = this.smsForm.querySelector('.js-octocaptcha-token') as HTMLInputElement
    if (octocaptchaToken && octocaptchaToken.value) {
      formData.append('octocaptcha-token', octocaptchaToken.value)
    }

    const response = await fetch(sendSmsUrl, {
      mode: 'same-origin',
      method: 'POST',
      body: formData,
      headers: {
        Accept: 'application/json',
        'Scoped-CSRF-Token': csrfInput.value,
        ...getBaseFetchHeaders(),
      },
    })

    if (response.ok && response.status === 200) {
      this.smsPhoneInput.disabled = true
      this.setSmsControlState(false, true)
    } else {
      this.setSmsControlState(false, false, await this.responseErrorMessage(response))
    }
  }

  @debounce(50)
  async otpChange() {
    const otpInput = this.configuringApp() ? this.appOtpInput : this.smsOtpInput
    const otpRe = new RegExp(`^([0-9]{6})$`)
    if (!otpRe.test(otpInput.value)) {
      return
    }
    // disable the input while we're verifying the otp. this prevent multiple events from verifying or the input
    // from freezing (i.e. successful verification) on a bad code.
    otpInput.disabled = true

    const resp = await this.verifyOtp(otpInput.value)
    if (resp.success) {
      this.clearError()
      this.saveButton.disabled = false
      otpInput.disabled = true
      this.otpVerifySuccess.hidden = false
    } else {
      // eslint-disable-next-line i18n-text/no-en
      this.setError(resp.error || 'Unable to verify OTP. Please try again.')
      // re-enable the input and focus it
      otpInput.disabled = false
      otpInput.focus()
    }
  }

  setError(message: string) {
    this.verifyError.textContent = message
    this.verifyError.hidden = false
    announce(message)
  }

  clearError() {
    this.verifyError.textContent = ''
    this.verifyError.hidden = true
  }

  async verifyOtp(otp: string): Promise<VerifyResponse> {
    const form = this.configuringApp() ? this.appForm : this.smsForm
    const type = this.configuringApp() ? 'app' : 'sms'
    const csrfInput = form.querySelector('.js-data-url-csrf') as HTMLInputElement
    const formData = new FormData()
    formData.append('type', type)
    formData.append('otp', otp.trim())

    const response = await fetch(form.action, {
      mode: 'same-origin',
      method: 'POST',
      body: formData,
      headers: {
        Accept: 'application/json',
        'Scoped-CSRF-Token': csrfInput.value,
        ...getBaseFetchHeaders(),
      },
    })

    if (response.status !== 200) {
      return {
        success: false,
        error: await this.responseErrorMessage(response),
      }
    }
    return {success: true}
  }

  async responseErrorMessage(response: Response): Promise<string> {
    try {
      const jsonResponse = await response.json()
      return jsonResponse['error']
    } catch {
      if (response.status >= 400 && response.status < 500) {
        // eslint-disable-next-line i18n-text/no-en
        return 'Unauthorized to complete request. Try refreshing the page or contact support.'
      }
      // eslint-disable-next-line i18n-text/no-en
      return 'Server encountered an error. Please try again.'
    }
  }
}
